From df9ea4c4b6bcbe20b0d1e48a83d93a6355d5a51e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:19:30 +0100
Subject: [PATCH] klipper: Make the Meta+V popup resizable and remember its
 size

The popup could only be resized with Meta+right-drag, and it went back
to its default size every time it opened. Let its edges be dragged like
the system tray popup and save the size the user picks in state config.

BUG: 496475
---
 klipper/declarative/qml/KlipperPopup.qml |  3 ++
 klipper/klipperpopup.cpp                 | 66 +++++++++++++++++++++++-
 klipper/klipperpopup.h                   | 10 ++++
 3 files changed, 77 insertions(+), 2 deletions(-)

diff --git a/klipper/declarative/qml/KlipperPopup.qml b/klipper/declarative/qml/KlipperPopup.qml
index 3d55c2c92b..9b797782ec 100644
--- a/klipper/declarative/qml/KlipperPopup.qml
+++ b/klipper/declarative/qml/KlipperPopup.qml
@@ -8,6 +8,7 @@ pragma ComponentBehavior: Bound

 import QtQuick
 import QtQuick.Controls as QQC
+import QtQuick.Layouts
 import QtQuick.Window

 import org.kde.plasma.extras as PlasmaExtras
@@ -19,6 +20,8 @@ PlasmaExtras.Representation {

     implicitWidth: 100 // A friendly initial size
     implicitHeight: 100
+    Layout.minimumWidth: Kirigami.Units.gridUnit * 15
+    Layout.minimumHeight: Kirigami.Units.gridUnit * 10

     signal requestHidePopup()

diff --git a/klipper/klipperpopup.cpp b/klipper/klipperpopup.cpp
index 6ebc0171e9..eb2219784a 100644
--- a/klipper/klipperpopup.cpp
+++ b/klipper/klipperpopup.cpp
@@ -11,10 +11,14 @@
 #include <QDBusConnection>
 #include <QDBusMessage>
 #include <QDBusReply>
+#include <QMouseEvent>
 #include <QQmlEngine>
+#include <QQmlProperty>
 #include <QQuickItem>

+#include <KConfigGroup>
 #include <KLocalizedString>
+#include <KSharedConfig>

 #include <Plasma/Plasma>
 #include <PlasmaQuick/PlasmaQuick>
@@ -47,6 +51,9 @@ KlipperPopup::KlipperPopup()
     connect(item, SIGNAL(requestHidePopup()), this, SLOT(hide()));

     connect(qGuiApp, &QGuiApplication::focusWindowChanged, this, &KlipperPopup::onFocusWindowChanged);
+
+    const KConfigGroup config = KSharedConfig::openStateConfig()->group(u"klipper"_s).group(u"Popup"_s);
+    m_savedSize = QSize(config.readEntry("popupWidth", 0), config.readEntry("popupHeight", 0));
 }

 KlipperPopup::~KlipperPopup()
@@ -82,16 +89,30 @@ void KlipperPopup::showCurrentBarcode()

 void KlipperPopup::hide()
 {
+    // Only remember the size when the user resized the popup, so the default size keeps following the screen size
+    if (isVisible() && size() != m_appliedSize) {
+        m_savedSize = size().shrunkBy(padding());
+        KConfigGroup config = KSharedConfig::openStateConfig()->group(u"klipper"_s).group(u"Popup"_s);
+        config.writeEntry("popupWidth", m_savedSize.width());
+        config.writeEntry("popupHeight", m_savedSize.height());
+        config.sync();
+    }
+
     QWindow::hide();
     destroy(); // Required to recreate wl_surface
 }

 void KlipperPopup::resizePopup()
 {
+    const QSize minimumSize(QQmlProperty::read(mainItem(), u"Layout.minimumWidth"_s, qmlContext(mainItem())).toInt(),
+                            QQmlProperty::read(mainItem(), u"Layout.minimumHeight"_s, qmlContext(mainItem())).toInt());
+    setMinimumSize(minimumSize.grownBy(padding()));
+
+    const QSize contentSize = m_savedSize.isEmpty() ? QSize(mainItem()->implicitWidth(), mainItem()->implicitHeight()) : m_savedSize.expandedTo(minimumSize);
     // If the popup is off-screen, move it to the closest edge of the screen
-    const QSize popupSize = QSize(mainItem()->implicitWidth(), mainItem()->implicitHeight()).grownBy(padding()).boundedTo(screen()->availableSize());
+    m_appliedSize = contentSize.grownBy(padding()).boundedTo(screen()->availableSize());

-    resize(popupSize);
+    resize(m_appliedSize);
 }

 void KlipperPopup::showEvent(QShowEvent *event)
@@ -100,6 +121,47 @@ void KlipperPopup::showEvent(QShowEvent *event)
     requestActivate();
 }

+void KlipperPopup::mouseMoveEvent(QMouseEvent *event)
+{
+    PlasmaWindow::mouseMoveEvent(event);
+
+    const Qt::Edges edges = edgesAt(event->position());
+    if (edges == Qt::Edges(Qt::LeftEdge | Qt::TopEdge) || edges == Qt::Edges(Qt::RightEdge | Qt::BottomEdge)) {
+        setCursor(Qt::SizeFDiagCursor);
+    } else if (edges == Qt::Edges(Qt::RightEdge | Qt::TopEdge) || edges == Qt::Edges(Qt::LeftEdge | Qt::BottomEdge)) {
+        setCursor(Qt::SizeBDiagCursor);
+    } else if (edges & (Qt::LeftEdge | Qt::RightEdge)) {
+        setCursor(Qt::SizeHorCursor);
+    } else if (edges) {
+        setCursor(Qt::SizeVerCursor);
+    } else if (m_overridingCursor) {
+        unsetCursor();
+    }
+    m_overridingCursor = edges != Qt::Edges();
+}
+
+void KlipperPopup::mousePressEvent(QMouseEvent *event)
+{
+    const Qt::Edges edges = edgesAt(event->position());
+    if (edges && event->button() == Qt::LeftButton) {
+        startSystemResize(edges);
+        event->accept();
+        return;
+    }
+    PlasmaWindow::mousePressEvent(event);
+}
+
+Qt::Edges KlipperPopup::edgesAt(const QPointF &position) const
+{
+    const QMargins margins = padding();
+    Qt::Edges edges;
+    edges.setFlag(Qt::LeftEdge, position.x() < margins.left());
+    edges.setFlag(Qt::RightEdge, position.x() >= width() - margins.right());
+    edges.setFlag(Qt::TopEdge, position.y() < margins.top());
+    edges.setFlag(Qt::BottomEdge, position.y() >= height() - margins.bottom());
+    return edges;
+}
+
 void KlipperPopup::positionOnScreen()
 {
     const QList<QScreen *> screens = QGuiApplication::screens();
diff --git a/klipper/klipperpopup.h b/klipper/klipperpopup.h
index f668ccc1eb..d3bd26fce1 100644
--- a/klipper/klipperpopup.h
+++ b/klipper/klipperpopup.h
@@ -31,10 +31,13 @@ public Q_SLOTS:

 protected:
     void showEvent(QShowEvent *event) override;
+    void mouseMoveEvent(QMouseEvent *event) override;
+    void mousePressEvent(QMouseEvent *event) override;

 private:
     void positionOnScreen();
     void onFocusWindowChanged(QWindow *focusWindow);
+    Qt::Edges edgesAt(const QPointF &position) const;

     /**
      * The "document" (clipboard history)
@@ -42,4 +45,11 @@ private:
     std::shared_ptr<HistoryModel> m_model;

     std::shared_ptr<QQmlEngine> m_engine;
+
+    /**
+     * The size the user picked by resizing the popup, without padding
+     */
+    QSize m_savedSize;
+    QSize m_appliedSize;
+    bool m_overridingCursor = false;
 };
